"""Wrap the animation JSON as a script for the browser client.
usage: python3 build_webjs.py art/mainos-anim.json web/adart-data.js
"""
import sys

data = open(sys.argv[1]).read().strip()
open(sys.argv[2], 'w').write(
    '// Generated by art/tools/build_webjs.py from art/mainos-anim.json. Do not edit by hand.\n'
    'window.AdArtData = ' + data + ';\n')
